def find_degree_and_next_value(n, values):
    def calculate_differences(values):
        return [values[i + 1] - values[i] for i in range(len(values) - 1)]

    def find_degree(differences):
        if all(diff == differences[0] for diff in differences):
            return 1
        else:
            return 1 + find_degree(calculate_differences(differences))

    differences = values[:]
    degree = 0
    while not all(diff == differences[0] for diff in differences):
        differences = calculate_differences(differences)
        degree += 1

    next_value = values[-1] + differences[0]
    return degree, next_value

import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])
values = list(map(int, data[1:]))

degree, next_value = find_degree_and_next_value(n, values)
print(degree, next_value)
